/**
 * AssetId-based registry for Blender-published GLBs.
 * PACK_GLTF is the runtime URL map used by R3F.
 */
export type AssetRecord = {
  assetId: string;
  kind: string;
  folder: string;
  url: string;
  componentIds?: string[];
  brandId?: string;
  buildingId?: string;
  footprintMeters?: { width: number; depth: number };
  heightMeters?: number;
};

